# Apply 90° counter-clockwise rotation
def rotate_ccw(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])
    result = [[0] * n_rows for _ in range(n_cols)]
    for r in range(n_rows):
        for c in range(n_cols):
            result[n_cols - 1 - c][r] = grid[r][c]
    return result

